css:
.settings {
  max-inline-size: 40rem;
  margin-inline: auto;
  padding: var(--va-space-inline-lg);
  font-family: var(--va-font-family-ui);
  color: var(--va-color-text-default);
}

.settings h1,
.settings h2 {
  font-family: var(--va-font-family-reading);
  font-weight: var(--va-font-weight-bold);
  margin: 0;
}

.settings h2 {
  font-size: var(--va-font-size-lg);
}

.settings__header {
  margin-block-end: var(--va-space-inline-lg);
}

.settings__intro,
.settings__lead {
  color: var(--va-color-text-muted);
  margin-block: var(--va-space-inline-xs) 0;
}

.settings__intro {
  font-size: var(--va-font-size-md);
}

.settings__lead {
  font-size: var(--va-font-size-sm);
}

.settings__panel {
  padding-block: var(--va-space-inline-lg);
}

.settings__fields,
.settings__switches {
  display: flex;
  flex-direction: column;
  gap: var(--va-space-inline-lg);
  margin-block-start: var(--va-space-inline-lg);
}

.settings__switches {
  padding: var(--va-space-inline-lg);
  border: 1px solid var(--va-color-border-subtle);
  border-radius: var(--va-radius-surface);
  background: var(--va-color-surface-default);
}

.settings__actions {
  display: flex;
  gap: var(--va-space-gap-md);
  margin-block-start: var(--va-space-inline-lg);
}
